import React,{useEffect,useMemo,useRef,useState}from'react';
import{createRoot}from'react-dom/client';
import{Activity,AlertTriangle,ArrowRight,Award,BadgeCheck,BookMarked,BookOpen,Bookmark,BookmarkCheck,Building2,Check,CheckCircle2,ChevronLeft,ChevronRight,Circle,CircleHelp,ClipboardCheck,Clock,Compass,Database,Download,ExternalLink,Eye,FileCheck,FileCheck2,FileText,Files,Filter,FlaskConical,GitBranch,GraduationCap,Home,Image as ImageIcon,Inbox,Info,Layers3,Library,Lightbulb,Lock,Map as MapIcon,Maximize2,Menu,MessageSquareText,Milestone,PanelLeftClose,PanelLeftOpen,Pause,Play,RefreshCw,RotateCcw,Route,Scale,Search,ShieldCheck,Sparkles,StickyNote,Table2,Target,Trees,Trophy,X,Zap,ZoomIn,ZoomOut}from'lucide-react';
import HydroGuide from'./hydro';
import popDataUrl from'./data/pop-content.json?url';
import flowDataUrl from'./data/flowcharts-content.json?url';
import{featuredMedia,flowSpecs,questionBank,scenarios,trackGroups,tracks}from'./courseData';
import{loadProfile,saveProfile,hasAccount,registerCertificate,certificateSvg,downloadSvg,listUsers,switchUser,createUser,deleteUser,exportBackup,importBackup,progressKey}from'./profile';
import{resumoDaNorma}from'./leiResumos';
import'./styles.css';

const[popData,flowData]=await Promise.all([
 fetch(popDataUrl).then(r=>r.json()),
 fetch(flowDataUrl).then(r=>r.json()),
]);

// Sob deploy em subcaminho (GitHub Pages), os caminhos absolutos dos dados precisam do prefixo da base
const BASE=(import.meta.env.BASE_URL||'/').replace(/\/$/,'');
const wb=p=>typeof p==='string'&&p.startsWith('/')?BASE+p:p;
if(BASE){const PATH_KEYS=new Set(['publicPath','src','poster','captions']);const walk=o=>{if(Array.isArray(o))o.forEach(walk);else if(o&&typeof o==='object'){for(const k of Object.keys(o)){if(PATH_KEYS.has(k)&&typeof o[k]==='string'&&o[k].startsWith('/'))o[k]=BASE+o[k];else walk(o[k])}}};walk(popData);walk(flowData);walk(featuredMedia);}

const TRACK_ICONS={Compass,Scale,Inbox,GitBranch,FileCheck,Milestone,RefreshCw,ShieldCheck,Files,Map:MapIcon,Trees,Building2,ClipboardCheck,BadgeCheck,Library};

const STORAGE_KEY='academia-iat-progress-v2';
const NAV=[['dashboard','Visão geral',Home],['hidreletricas','Hidrelétricas',Zap],['formacao','Formação',BookOpen],['fluxos','Fluxogramas',GitBranch],['laboratorio','Laboratório',FlaskConical],['avaliacoes','Avaliações',ClipboardCheck],['biblioteca','Biblioteca',Library],['perfil','Meu perfil',BadgeCheck],['suporte','Suporte',CircleHelp]];
const blockMap=new Map(popData.blocks.map(b=>[b.id,b]));
const tableMap=new Map(popData.tables.map(t=>[t.id,t]));
const figureByBlock=new Map(popData.figures.map(f=>[f.blockId,f]));
const sectionMap=new Map(popData.sections.map(s=>[s.id,s]));

function useStoredState(){
 const key=useMemo(()=>{try{return progressKey()}catch{return STORAGE_KEY}},[]);
 const initial={completed:[],bookmarks:[],notes:{},quizScores:{},labs:{},lastLesson:null,videoSeen:[],streak:1};
 const[state,setState]=useState(()=>{try{return{...initial,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{return initial}});
 useEffect(()=>{localStorage.setItem(key,JSON.stringify(state))},[state,key]);
 return[state,setState];
}
function norm(v=''){return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function assignedTrack(section){
 const n=section.number||'';
 if(/^18\.(10|11|12|13)/.test(n))return'm09';
 if(/^(Anexo|Referências)/.test(n))return'm14';
 const root=n.includes('.')?n.split('.')[0]:n;
 for(const t of tracks){if(t.id==='m09'||t.id==='m14')continue;if(t.sections.includes(root)||(!n&&t.id==='m00'))return t.id}
 return'm14';
}
const lessons=popData.sections.filter(s=>s.title&&!/sumário navegável|índice de fluxogramas|índice navegável/i.test(s.title)).map((s,i)=>({...s,trackId:assignedTrack(s),order:i,minutes:Math.max(4,Math.min(28,Math.round((s.blockIds?.length||1)*1.8)+4))}));
const lessonMap=new Map(lessons.map(l=>[l.id,l]));
const trackLessons=new Map(tracks.map(t=>[t.id,lessons.filter(l=>l.trackId===t.id)]));
function trackProgress(id,state){const ls=trackLessons.get(id)||[];return ls.length?Math.round(ls.filter(l=>state.completed.includes(l.id)).length/ls.length*100):0}
function sectionText(section){return(section.blockIds||[]).map(id=>{const b=blockMap.get(id);return b?.paragraph?.text||b?.caption||''}).filter(Boolean).join(' ')}
function firstLesson(trackId){return(trackLessons.get(trackId)||[])[0]}

const VIEW_IDS=['dashboard','hidreletricas','formacao','fluxos','laboratorio','avaliacoes','biblioteca','perfil','suporte'];
function parseHash(){const h=((typeof location!=='undefined'&&location.hash)||'').replace(/^#\/?/,'');if(!h)return{view:'dashboard',lesson:null};const i=h.indexOf('/');const seg=i<0?h:h.slice(0,i);const rest=i<0?'':h.slice(i+1);if(seg==='aula'&&rest)return{view:'lesson',lesson:decodeURIComponent(rest)};if(VIEW_IDS.includes(seg))return{view:seg,lesson:null};return{view:'dashboard',lesson:null};}
function reloadFade(){document.body.classList.add('page-leave');setTimeout(()=>location.reload(),240)}
function pushHash(t){if(typeof location==='undefined')return;if(location.hash===t)return;try{history.pushState(null,'',t)}catch{location.hash=t}}
function App(){
 const [profile,setProfileRaw]=useState(()=>loadProfile());
 const setProfile=(p)=>{const v=typeof p==='function'?p(profile):p;setProfileRaw(v);saveProfile(v);};
 const[state,setState]=useStoredState();
 const _init=parseHash();
 const[view,setView]=useState(_init.view);
 const[selectedLesson,setSelectedLesson]=useState(()=>_init.lesson&&lessonMap.has(_init.lesson)?_init.lesson:(lessonMap.has(state.lastLesson)?state.lastLesson:firstLesson('m00')?.id));
 const[menuOpen,setMenuOpen]=useState(false),[searchOpen,setSearchOpen]=useState(false),[toast,setToast]=useState('');
 const progress=Math.round(state.completed.length/lessons.length*100);
 useEffect(()=>{const fn=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true)}if(e.key==='Escape')setSearchOpen(false)};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[]);
 useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(''),2600);return()=>clearTimeout(id)}},[toast]);
 useEffect(()=>{const onNav=()=>{const p=parseHash();if(p.view==='lesson'){if(p.lesson&&lessonMap.has(p.lesson)){setSelectedLesson(p.lesson);setState(s=>s.lastLesson===p.lesson?s:{...s,lastLesson:p.lesson})}setView('lesson')}else setView(p.view);setMenuOpen(false);setSearchOpen(false)};window.addEventListener('popstate',onNav);window.addEventListener('hashchange',onNav);return()=>{window.removeEventListener('popstate',onNav);window.removeEventListener('hashchange',onNav)}},[]);
 function go(next){setView(next);setMenuOpen(false);pushHash(next==='dashboard'?'#/':'#/'+next);scrollTo({top:0,behavior:'smooth'})}
 function openLesson(id){if(!id)return;setSelectedLesson(id);setState(s=>({...s,lastLesson:id}));setView('lesson');setSearchOpen(false);setMenuOpen(false);pushHash('#/aula/'+encodeURIComponent(id));scrollTo({top:0,behavior:'smooth'})}
 function complete(id){setState(s=>({...s,completed:s.completed.includes(id)?s.completed.filter(x=>x!==id):[...s.completed,id]}));setToast(state.completed.includes(id)?'Aula marcada como não concluída':'Aula concluída e progresso salvo')}
 function bookmark(id){setState(s=>({...s,bookmarks:s.bookmarks.includes(id)?s.bookmarks.filter(x=>x!==id):[...s.bookmarks,id]}));setToast(state.bookmarks.includes(id)?'Favorito removido':'Aula salva nos favoritos')}
 let content={dashboard:<Dashboard state={state} progress={progress} go={go} openLesson={openLesson}/>,hidreletricas:<HydroGuide go={go}/>,formacao:<Formation state={state} openLesson={openLesson}/>,fluxos:<Flowcharts state={state} setState={setState}/>,laboratorio:<Laboratory state={state} setState={setState}/>,avaliacoes:<Assessments state={state} setState={setState}/>,biblioteca:<KnowledgeLibrary state={state} openLesson={openLesson}/>,perfil:<Profile state={state} progress={progress} profile={profile} setProfile={setProfile} go={go} openLesson={openLesson}/>,suporte:<Suporte/>,lesson:<Lesson lesson={lessonMap.get(selectedLesson)||lessons[0]} state={state} setState={setState} openLesson={openLesson} complete={complete} bookmark={bookmark} go={go}/>}[view];
 return <div className="app-shell">
  <Topbar onMenu={()=>setMenuOpen(v=>!v)} onSearch={()=>setSearchOpen(true)} progress={progress} profile={profile} onProfile={()=>go('perfil')}/>
  <Sidebar view={view} go={go} open={menuOpen} openLesson={openLesson}/>
  {menuOpen&&<button className="nav-scrim" aria-label="Fechar menu" onClick={()=>setMenuOpen(false)}/>} 
  <main className={'main '+(view==='lesson'?'lesson-main':'')}><div className="view-anim" key={view==='lesson'?'l:'+selectedLesson:view}>{content}</div></main>
  {searchOpen&&<GlobalSearch close={()=>setSearchOpen(false)} openLesson={openLesson}/>} 
  {toast&&<div className="toast"><CheckCircle2/>{toast}</div>}
 </div>
}

function Profile({state,progress,profile,setProfile,go,openLesson}){
 const conta=hasAccount(profile);
 const [editando,setEditando]=useState(!conta);
 const [form,setForm]=useState({name:profile.name||'',role:profile.role||'',unit:profile.unit||''});
 const salvar=(e)=>{e&&e.preventDefault&&e.preventDefault();const nome=(form.name||'').trim();if(!nome)return;setProfile(pr=>({...pr,name:nome,role:(form.role||'').trim(),unit:(form.unit||'').trim(),createdAt:pr.createdAt||new Date().toISOString()}));setEditando(false);};
 const mods=tracks.map(t=>({t,p:trackProgress(t.id,state)}));
 const concluidos=mods.filter(m=>m.p===100).length;
 const hoje=()=>new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
 const build=typeof __BUILD_STAMP__!=='undefined'?__BUILD_STAMP__:'local';
 const baixarCert=(label,percent)=>{const nowIso=new Date().toISOString();setProfile(pr=>registerCertificate(pr,label,percent,nowIso));const svg=certificateSvg({name:profile.name,label,dateLabel:'Emitido em '+hoje(),percent,buildId:build});downloadSvg('certificado-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,40)+'.svg',svg);};
 if(!conta||editando){
  return <div className="page profile-page"><PageHeader icon={BadgeCheck} kicker="Meu perfil" title={conta?'Editar meu perfil':'Criar meu perfil'} subtitle="Seu progresso e seus certificados ficam vinculados a este perfil."/>
   <form className="profile-form" onSubmit={salvar}><div className="form-avatar" aria-hidden="true">{((form.name||'').trim().split(/\s+/).filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase())||'?'}</div><label>Nome<input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="Como você quer ser identificado" required autoFocus/></label>
   <label>Cargo ou função<input value={form.role} onChange={e=>setForm(f=>({...f,role:e.target.value}))} placeholder="Opcional"/></label>
   <label>Órgão ou setor<input value={form.unit} onChange={e=>setForm(f=>({...f,unit:e.target.value}))} placeholder="Opcional"/></label>
   <div className="profile-actions"><button type="submit" className="primary">{conta?'Salvar':'Criar perfil'} <Check/></button>{conta&&<button type="button" className="text-action" onClick={()=>setEditando(false)}>Cancelar</button>}</div>
   <p className="profile-note">Registro pessoal de estudo, guardado apenas neste navegador. Não é login seguro nem credencial institucional do IAT.</p></form>
   <div className="profile-restore-alt"><span>Já estudava em outro computador?</span><label className="text-action file-action">Restaurar backup<input type="file" accept="application/json" onChange={e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{const r=importBackup(t);if(r.ok)reloadFade();else alert(r.error)})}}/></label></div></div>;
 }
 return <div className="page profile-page"><PageHeader icon={BadgeCheck} kicker="Meu perfil" title={profile.name} subtitle={[profile.role,profile.unit].filter(Boolean).join(' · ')||'Registro pessoal de estudo'}/>
  <section className="profile-grid">
   <article className="profile-card profile-progress"><h3>Progresso do curso</h3><div className="pring" style={{'--v':progress}}><strong>{progress}%</strong></div><small>{state.completed.length} de {lessons.length} tópicos concluídos</small><small>{concluidos} de {tracks.length} módulos completos</small></article>
   <article className="profile-card profile-personal"><h3>Meus dados</h3><dl><dt>Nome</dt><dd>{profile.name}</dd><dt>Cargo</dt><dd>{profile.role||'-'}</dd><dt>Órgão</dt><dd>{profile.unit||'-'}</dd><dt>Desde</dt><dd>{profile.createdAt?new Date(profile.createdAt).toLocaleDateString('pt-BR'):'-'}</dd></dl><button className="text-action" onClick={()=>{setForm({name:profile.name,role:profile.role,unit:profile.unit});setEditando(true);}}>Editar dados</button></article>
   <article className="profile-card profile-activity"><h3>Atividade</h3><ul className="profile-activity-list"><li><Bookmark size={15}/> {state.bookmarks.length} favoritos</li><li><StickyNote size={15}/> {Object.values(state.notes||{}).filter(v=>v&&v.trim()).length} anotações</li><li><CheckCircle2 size={15}/> {state.completed.length} tópicos feitos</li></ul>{state.lastLesson&&<button className="text-action" onClick={()=>openLesson(state.lastLesson)}>Continuar de onde parou <ArrowRight size={15}/></button>}</article>
  </section>
  <section className="profile-users"><div className="section-title"><div><h2>Perfis neste navegador</h2><p>Troque de usuário, crie um novo perfil ou leve seu estudo para outro computador por backup.</p></div></div>
   <ul className="user-list">{listUsers().map(u=><li key={u.id} className={u.active?'active':''}><span className="u-ini">{((u.name||'?').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())||'?'}</span><span className="u-name">{u.name}{u.role?<small> · {u.role}</small>:null}</span>{u.active?<em>ativo</em>:<><button className="text-action" onClick={()=>{switchUser(u.id);reloadFade()}}>Entrar</button><button className="u-del" title="Excluir perfil" onClick={()=>{if(confirm(`Excluir o perfil "${u.name}" e o progresso dele neste navegador?`)){deleteUser(u.id);reloadFade()}}}><X size={14}/></button></>}</li>)}</ul>
   <div className="profile-actions-row"><button className="text-action" onClick={()=>{createUser();reloadFade()}}>+ Novo perfil</button><button className="text-action" onClick={()=>exportBackup()}><Download size={14}/> Baixar backup</button><label className="text-action file-action">Restaurar backup<input type="file" accept="application/json" onChange={e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{const r=importBackup(t);if(r.ok)reloadFade();else alert(r.error)})}}/></label></div>
   <p className="profile-note">Cada perfil guarda progresso próprio, apenas neste navegador. Para continuar em outro computador, baixe o backup aqui e restaure lá.</p></section>
  <section className="profile-cert-block"><div className="section-title"><div><h2>Certificados</h2><p>Marcos de conclusão que você pode baixar. Cada um é um registro pessoal de estudo.</p></div><Award/></div>
   <div className="cert-course">{progress===100?<button className="primary" onClick={()=>baixarCert('Curso completo do POP',100)}><Download size={16}/> Baixar certificado do curso</button>:<div className="cert-locked-wrap"><p className="cert-locked">Conclua os {lessons.length} tópicos para liberar o certificado do curso completo. Faltam {lessons.length-state.completed.length}.</p><i className="cert-bar"><em style={{width:progress+'%'}}/></i><small>{progress}% do percurso concluído</small></div>}</div>
   {(profile.certificates||[]).length>0&&<div className="cert-history"><h4>Marcos emitidos</h4><ul>{(profile.certificates||[]).map(c=><li key={c.id}><Award size={14}/><span>{c.label}</span><small>{c.at?new Date(c.at).toLocaleDateString('pt-BR'):''} · {c.percent}%</small></li>)}</ul></div>}<h4>Por módulo</h4><ul className="cert-modules">{mods.map(({t,p})=><li key={t.id}><span className="cert-mod-code">{t.code}</span><span className="cert-mod-title">{t.title}</span><span className="cert-mod-bar"><i style={{width:p+'%'}}/></span><span className="cert-mod-pct">{p}%</span>{p===100?<button className="cert-mod-dl" onClick={()=>baixarCert('Módulo '+t.code+' · '+t.title,100)}><Download size={14}/></button>:<span className="cert-mod-pending">em curso</span>}</li>)}</ul></section>
  <p className="profile-note">Os certificados desta plataforma são registros pessoais de autoestudo. Não são documentos oficiais do Instituto Água e Terra.</p></div>;
}
function Suporte(){return <div className="page suporte-page"><PageHeader icon={CircleHelp} kicker="Fale com quem mantém a plataforma" title="Suporte" subtitle="Dúvidas, sugestões de conteúdo ou correções: escreva diretamente ao responsável."/>
 <section className="suporte-card"><div className="sup-avatar">RV</div><div className="sup-info"><h2>Rafael Valgrande Augusto</h2><p className="sup-cargo">Engenheiro Sanitarista e Ambiental</p><a className="sup-mail" href="mailto:bol.rafaelaugusto@iat.pr.gov.br?subject=Academia%20IAT%3A%20d%C3%BAvida%20ou%20sugest%C3%A3o"><MessageSquareText size={16}/> bol.rafaelaugusto@iat.pr.gov.br</a><p className="sup-note">Ao escrever, diga em qual módulo, aula ou tela está a dúvida ou a sugestão: isso acelera a resposta e a correção.</p></div></section>
 <section className="suporte-tipos">{[['Dúvida de conteúdo','Algo no material parece incompleto, confuso ou desatualizado.'],['Sugestão','Ideia de melhoria, novo exercício ou tema a aprofundar.'],['Problema técnico','Algo não abre, não salva ou não funciona como deveria.']].map(([t,d])=><article key={t}><strong>{t}</strong><p>{d}</p></article>)}</section></div>}
function Topbar({onMenu,onSearch,progress,profile,onProfile}){const _n=((profile&&profile.name)||'').trim();const _acc=hasAccount(profile);const _ini=_acc?(_n.split(/\s+/).filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase()||'IAT'):'+';return <header className="topbar"><button className="mobile-menu" onClick={onMenu} aria-label="Abrir menu"><Menu/></button><div className="compact-brand"><span className="brand-wave">IAT</span><div><strong>Academia de Licenciamento</strong><small>Hidrelétrico</small></div></div><button className="global-search" onClick={onSearch}><Search/><span>Buscar no POP, aulas e checklists</span><kbd>Ctrl K</kbd></button><div className="top-progress" title={`${progress}% concluído`}><span>{progress}%</span><i><em style={{width:`${progress}%`}}/></i></div><button className="profile" onClick={onProfile} title={_acc?'Ver meu perfil':'Criar meu perfil'}><span>{_ini}</span><div><strong>{_acc?_n.split(/\s+/)[0]:'Meu perfil'}</strong><small>{_acc?(profile.role||'Registro pessoal'):'Criar sua conta'}</small></div></button></header>}
function Sidebar({view,go,open,openLesson}){return <aside className={'sidebar-v2 '+(open?'open':'')}><div className="brand-panel"><strong>Academia IAT</strong><span>Licenciamento<br/>Hidrelétrico</span><svg viewBox="0 0 200 128" aria-hidden="true" className="brand-hydro">
<rect x="8" y="52" width="62" height="26" rx="3" fill="#57d8bf" opacity=".85"/>
<path d="M10 56 q8 -4 16 0 t16 0 t16 0 t14 0" stroke="#eafff7" strokeWidth="2.5" fill="none"/>
<path d="M70 46 L70 92 L92 92 L84 46 Z" fill="#e6efe9" stroke="#a8d5c2" strokeWidth="1.5"/>
<path d="M74 52 L74 88 M79 56 L80 88 M84 62 L86 88" stroke="#9db8ab" strokeWidth="1.4"/>
<path d="M86 58 L112 84" stroke="#0b3b2d" strokeWidth="5" strokeLinecap="round"/>
<path d="M86 58 L112 84" stroke="#57d8bf" strokeWidth="2" strokeLinecap="round" strokeDasharray="4 6"/>
<rect x="110" y="76" width="30" height="18" rx="2" fill="#fff" stroke="#57d8bf" strokeWidth="1.6"/>
<path d="M110 76 L125 66 L140 76 Z" fill="#57d8bf"/>
<path d="M124 80 l-4 7 h4 l-3 7 8 -9 h-4 l4 -5 Z" fill="#f3bd4f"/>
<path d="M150 44 L150 94 M141 58 L159 58 M143 48 L157 48" stroke="#eafff7" strokeWidth="2.6"/>
<path d="M140 94 L160 94" stroke="#eafff7" strokeWidth="2.6"/>
<path d="M150 44 C162 38 174 42 186 34" stroke="#f3bd4f" strokeWidth="2" fill="none"/>
<circle cx="188" cy="33" r="3.4" fill="#f3bd4f"/>
<g transform="translate(18 88)">
<path d="M0 12 C10 4 24 4 34 9 C44 4 58 4 68 12 L68 32 C58 25 44 25 34 29 C24 25 10 25 0 32 Z" fill="#fff" stroke="#57d8bf" strokeWidth="2.4"/>
<path d="M34 9 L34 29" stroke="#57d8bf" strokeWidth="2.2"/>
<path d="M7 14 L28 12 M7 19 L28 17 M7 24 L28 22 M40 12 L61 14 M40 17 L61 19 M40 22 L61 24" stroke="#0b3b2d" strokeWidth="1.5" opacity=".55"/>
<path d="M26 -2 L42 -2 L34 3 Z M34 -2 L34 -8 M30 -8 L38 -8" stroke="#f3bd4f" strokeWidth="2" fill="#f3bd4f"/>
</g>
</svg></div><nav>{NAV.map(([id,label,Icon])=><button key={id} className={view===id||(view==='lesson'&&id==='formacao')?'active':''} onClick={()=>go(id)}><Icon/>{label}</button>)}</nav><button className="sidebar-help" onClick={()=>openLesson&&openLesson(firstLesson('m00')?.id)}><CircleHelp/><div><strong>Por onde começar?</strong><small>Abra o módulo de Orientação</small></div><ChevronRight/></button><div className="source-lock"><ShieldCheck/><span>Conteúdo integral<br/><b>POP v{popData.metadata?.operational?.version||'1.2'} · {popData.metadata?.operational?.dateLabel||'julho de 2026'}</b></span></div></aside>}

function Dashboard({state,progress,go,openLesson}){
 const continueLesson=lessonMap.get(state.lastLesson)||firstLesson('m02');
 const continueTrack=tracks.find(t=>t.id===continueLesson.trackId);
 const feat={src:wb('/media/tour-usina.mp4'),poster:wb('/media/tour-usina-poster.png'),captions:wb('/media/tour-usina.vtt'),title:'Anatomia de uma usina em operação, tour guiado'};
 return <div className="page dashboard-page"><section className="dashboard-intro"><div><h1>Aprenda o procedimento.<br/>Pratique a decisão.</h1><p>Percorra o POP completo e desenvolva segurança para decidir com qualidade em cada etapa do licenciamento hidrelétrico.</p></div><div className="intro-stat"><span>Seu progresso</span><strong>{progress}%</strong><i><em style={{width:`${progress}%`}}/></i><small>{state.completed.length} de {lessons.length} tópicos concluídos</small></div></section>
 <section className="river-journey" aria-label="Percurso de aprendizagem"><div className="journey-head"><h2>Seu percurso pelo POP</h2><button onClick={()=>go('formacao')}>Ver formação completa <ArrowRight/></button></div><div className="river-line"><svg viewBox="0 0 1600 140" preserveAspectRatio="none" aria-hidden="true"><path className="river-shadow" d="M0 75 C120 10 230 125 350 62 S590 110 720 55 S950 110 1080 50 S1320 115 1600 52"/><path className="river-water" d="M0 75 C120 10 230 125 350 62 S590 110 720 55 S950 110 1080 50 S1320 115 1600 52"/></svg><div className="journey-track">{tracks.map((t,i)=>{let p=trackProgress(t.id,state);return <button key={t.id} style={{'--i':i}} title={t.code+' · '+t.title} className={p===100?'done':p>0?'current':''} onClick={()=>openLesson(firstLesson(t.id)?.id)}><span>{p===100?<Check/>:i+1}</span><strong>{t.code}</strong><small>{t.title}</small></button>})}</div></div><div className="journey-legend"><span><i className="dot done"/>Concluído</span><span><i className="dot current"/>Em andamento</span><span><i className="dot"/>Não iniciado</span></div></section>
 <section className="dashboard-feature"><div className="feature-media"><video key={feat?.src} poster={feat?.poster||wb("/media/analista-licenciamento.png")} controls preload="metadata" playsInline>{feat?.src&&<source src={feat.src} type="video/mp4"/>}{feat?.captions&&<track kind="captions" srcLang="pt" src={feat.captions} label="Português" default/>}</video><span>Vídeo em destaque{feat?.title?`: ${feat.title}`:""}</span><span className="fm-chip"><Clock/> 1:24 · 10 componentes</span></div><div className="feature-copy"><small>{continueTrack.code} · CONTINUE DE ONDE PAROU</small><h2>{continueLesson.fullTitle||continueLesson.title}</h2><p>{continueTrack.summary}</p><div className="feature-meta"><span><Clock/> {continueLesson.minutes} min</span><span><Layers3/> {trackLessons.get(continueTrack.id).length} tópicos</span></div><button className="primary" onClick={()=>openLesson(continueLesson.id)}>Continuar aula <Play/></button><button className="text-action" onClick={()=>go('formacao')}>Ver todas as aulas <ArrowRight/></button></div><TodayPlan go={go} openLesson={openLesson} continueLesson={continueLesson}/></section>
 <section className="dashboard-bottom"><article className="flow-preview"><div className="section-title"><div><h2>Prévia do fluxo geral</h2><p>Veja a análise ganhar forma, etapa por etapa.</p></div><button onClick={()=>go('fluxos')}>Explorar <ExternalLink/></button></div><MiniFlow/></article><article className="coverage-card"><div className="section-title"><div><h2>Todo o POP, em um só lugar</h2><p>Extração auditada e vinculada às aulas.</p></div><Database/></div><div className="coverage-stats"><span><strong>{lessons.length}</strong>seções e tópicos</span><span><strong>{popData.tables.length}</strong>quadros e tabelas</span><span><strong>{popData.figures.length+flowData.flowcharts.length}</strong>figuras e fluxos</span><span><strong>{(popData.stats?.allDocumentParagraphNodes||0).toLocaleString('pt-BR')}</strong>parágrafos</span></div><button onClick={()=>go('biblioteca')}>Abrir biblioteca integral <ArrowRight/></button></article></section></div>
}
function TodayPlan({go,openLesson,continueLesson}){const items=[[BookOpen,'Continuar aula',continueLesson?(continueLesson.number?`${continueLesson.number} `:'')+continueLesson.title:'Triagem e leitura do processo',()=>continueLesson&&openLesson?openLesson(continueLesson.id):go('formacao')],[FileCheck2,'Checklist','Conferência documental',()=>go('biblioteca')],[FlaskConical,'Laboratório','Simule uma análise',()=>go('laboratorio')],[ClipboardCheck,'Avaliação rápida','Teste seus conhecimentos',()=>go('avaliacoes')]];return <aside className="today-plan"><div><h2>Seu plano de hoje</h2><span>≈ 45 min</span></div>{items.map(([Icon,a,b,fn],i)=><button key={a} onClick={fn}><span className={`plan-icon c${i}`}><Icon/></span><span><strong>{a}</strong><small>{b}</small></span><ChevronRight/></button>)}</aside>}
function MiniFlow(){return <div className="mini-flow">{['Receber','Conferir','Enquadrar','Analisar','Registrar'].map((x,i)=><React.Fragment key={x}><div style={{'--delay':`${i*.35}s`}}><span>{i+1}</span><strong>{x}</strong></div>{i<4&&<i><ArrowRight/></i>}</React.Fragment>)}</div>}

function Formation({state,openLesson}){
 const[openTrack,setOpenTrack]=useState('m02'),[filter,setFilter]=useState('');
 return <div className="page"><PageHeader title="Formação completa" subtitle={`${tracks.length} módulos conectam cada seção do POP a objetivos, conteúdo-fonte, prática e avaliação.`} icon={GraduationCap}/><div className="formation-toolbar"><div><Search/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filtrar módulos ou aulas"/></div><span>{lessons.length} tópicos · {tracks.reduce((a,t)=>a+(trackLessons.get(t.id)?.reduce((x,l)=>x+l.minutes,0)||0),0)} min</span></div><div className="curriculum">{trackGroups.map(group=><section key={group.title}><div className="group-title"><span>{group.title}</span><i/></div>{group.ids.map(id=>{const t=tracks.find(x=>x.id===id),full=trackLessons.get(id)||[],ls=full.filter(l=>norm(l.title+' '+(l.number||'')).includes(norm(filter))),p=trackProgress(id,state),Icon=TRACK_ICONS[t.icon]||BookOpen;if(filter&&!norm(t.title+' '+t.code).includes(norm(filter))&&!ls.length)return null;const show=filter&&!ls.length?full:ls;const expanded=openTrack===id||(!!filter&&show.length>0);return <article className={'track-row '+(expanded?'expanded':'')} key={id}><button className="track-summary" onClick={()=>setOpenTrack(openTrack===id?'':id)}><span className="track-icon" style={{'--track':t.color}}><Icon/></span><span className="track-copy"><small>{t.code}</small><strong>{t.title}</strong><em>{t.summary}</em></span><span className="track-metrics"><b>{p}%</b><i><em style={{width:`${p}%`}}/></i><small>{state.completed.filter(x=>full.some(l=>l.id===x)).length}/{full.length} tópicos</small></span><ChevronRight/></button>{expanded&&<div className="lesson-list">{show.map(l=><button key={l.id} onClick={()=>openLesson(l.id)}><span className={state.completed.includes(l.id)?'complete':''}>{state.completed.includes(l.id)?<Check/>:full.indexOf(l)+1}</span><span><strong>{l.number?`${l.number} `:''}{l.title}</strong><small>{l.minutes} min · Conteúdo integral do POP</small></span>{state.bookmarks.includes(l.id)&&<BookmarkCheck className="saved"/>}<ChevronRight/></button>)}</div>}</article>})}</section>)}</div></div>
}

function Lesson({lesson,state,setState,openLesson,complete,bookmark,go}){
 const[tab,setTab]=useState('aula'),[outlineOpen,setOutlineOpen]=useState(true);const track=tracks.find(t=>t.id===lesson.trackId)||tracks[0];const media=featuredMedia[track.id];const ls=trackLessons.get(track.id)||[];const index=ls.findIndex(l=>l.id===lesson.id);const next=ls[index+1]||lessons[lesson.order+1];const blocks=(lesson.blockIds||[]).map(id=>blockMap.get(id)).filter(b=>b&&!b.navigationOnly);const tables=blocks.filter(b=>b.type==='table').map(b=>tableMap.get(b.tableId)).filter(Boolean);const figures=popData.figures.filter(f=>f.blockId&&lesson.blockIds?.includes(f.blockId));const note=state.notes[lesson.id]||'';
 useEffect(()=>{scrollTo({top:0})},[lesson.id]);
 function setNote(v){setState(s=>({...s,notes:{...s.notes,[lesson.id]:v}}))}
 return <div className={'lesson-layout '+(!outlineOpen?'outline-collapsed':'')}><aside className="lesson-outline"><button className="outline-toggle" onClick={()=>setOutlineOpen(v=>!v)}>{outlineOpen?<PanelLeftClose/>:<PanelLeftOpen/>}</button>{outlineOpen&&<><button className="back-course" onClick={()=>go('formacao')}><ChevronLeft/> Voltar à formação</button><div className="outline-track"><span style={{background:track.color}}>{track.code}</span><div><strong>{track.title}</strong><small>{trackProgress(track.id,state)}% concluído</small></div></div><div className="outline-lessons">{ls.map((l,i)=><button className={l.id===lesson.id?'active':''} key={l.id} onClick={()=>openLesson(l.id)}><span className={state.completed.includes(l.id)?'done':''}>{state.completed.includes(l.id)?<Check/>:i+1}</span><span>{l.number&&<small>{l.number}</small>}<strong>{l.title}</strong></span></button>)}</div></>}</aside><div className="lesson-content"><div className="breadcrumbs"><button onClick={()=>go('formacao')}>Formação</button><ChevronRight/><span>{track.code}</span><ChevronRight/><span>{lesson.number||'Introdução'}</span></div><header className="lesson-header"><div><h1>{lesson.number&&<span>{lesson.number}</span>} {lesson.title}</h1><p><Target/> Objetivo: compreender os critérios desta seção, aplicar o método ao caso concreto e registrar uma decisão rastreável.</p></div><button className="bookmark-btn" onClick={()=>bookmark(lesson.id)}>{state.bookmarks.includes(lesson.id)?<BookmarkCheck/>:<Bookmark/>}</button></header><VideoLesson media={media} track={track}/><div className="lesson-tabs" role="tablist">{[['aula','Aula',BookOpen],['fonte','Conteúdo integral',FileText],['materiais','Quadros e figuras',Layers3],['notas','Anotações',StickyNote]].map(([id,label,Icon])=><button role="tab" aria-selected={tab===id} className={tab===id?'active':''} onClick={()=>setTab(id)} key={id}><Icon/>{label}{id==='materiais'&&<span>{tables.length+figures.length}</span>}</button>)}</div><div className="tab-panel" key={tab}>{tab==='aula'&&<LessonOverview lesson={lesson} blocks={blocks} setTab={setTab} openLesson={openLesson} checked={state.checks?.[lesson.id]||[]} toggleCheck={i=>setState(s=>{const cur=s.checks?.[lesson.id]||[];const nx=cur.includes(i)?cur.filter(x=>x!==i):[...cur,i];return{...s,checks:{...(s.checks||{}),[lesson.id]:nx}}})}/>} {tab==='fonte'&&<SourceContent blocks={blocks}/>} {tab==='materiais'&&<LessonMaterials tables={tables} figures={figures}/>} {tab==='notas'&&<Notes value={note} setValue={setNote}/>}</div><footer className="lesson-footer"><button className={state.completed.includes(lesson.id)?'completed':''} onClick={()=>complete(lesson.id)}>{state.completed.includes(lesson.id)?<CheckCircle2/>:<Circle/>}{state.completed.includes(lesson.id)?'Aula concluída':'Marcar como concluída'}</button>{next&&<button className="next-lesson" onClick={()=>openLesson(next.id)}><span><small>PRÓXIMO TÓPICO</small><strong>{next.number?`${next.number} `:''}{next.title}</strong></span><ArrowRight/></button>}</footer></div><aside className="lesson-context"><div className="context-sticky"><h3>Nesta aula</h3><div className="context-progress"><span>Progresso do módulo</span><b>{trackProgress(track.id,state)}%</b><i><em style={{width:`${trackProgress(track.id,state)}%`}}/></i></div><nav><button className={tab==='aula'?'active':''} onClick={()=>setTab('aula')}><Target/>Resumo guiado{tab==='aula'?<CheckCircle2/>:<Circle/>}</button><button className={tab==='fonte'?'active':''} onClick={()=>setTab('fonte')}><FileText/>Texto integral{tab==='fonte'?<CheckCircle2/>:<Circle/>}</button><button className={tab==='materiais'?'active':''} onClick={()=>setTab('materiais')}><Layers3/>{tables.length} tabelas · {figures.length} figuras{tab==='materiais'?<CheckCircle2/>:<Circle/>}</button><button className={tab==='notas'?'active':''} onClick={()=>setTab('notas')}><StickyNote/>Caderno pessoal{tab==='notas'?<CheckCircle2/>:<Circle/>}</button></nav><div className="quick-tip"><Lightbulb/><div><strong>Regra de ouro</strong><p>Identifique documento, fundamento, suficiência, consequência e encaminhamento. Não comece pela conclusão.</p></div></div></div></aside></div>
}
function VideoLesson({media,track}){
 const ref=useRef(null);const[playing,setPlaying]=useState(false);const[rate,setRate]=useState(1);
 const play=()=>{ref.current&&ref.current.play()};
 const setSpeed=r=>{setRate(r);if(ref.current)ref.current.playbackRate=r};
 return <figure className={'video-lesson vl2 '+(playing?'playing':'')}>
  <div className="vl-stage">
   <video ref={ref} controls preload="metadata" poster={media.poster} playsInline onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onEnded={()=>setPlaying(false)}>
    <source src={media.src} type="video/mp4"/>
    <track default kind="captions" src={media.captions} srcLang="pt-BR" label="Português"/>
    Seu navegador não suporta vídeo HTML5.
   </video>
   {!playing&&<button className="vl-play" aria-label="Reproduzir videoaula" onClick={play}><Play/></button>}
  </div>
  <figcaption>
   <span><Play/>{media.title}</span>
   <span className="vl-tools"><small>Microaula animada · {track.code}</small>{[1,1.25,1.5].map(r=><button key={r} className={rate===r?'active':''} onClick={()=>setSpeed(r)} title={'Velocidade '+r+'x'}>{r}x</button>)}</span>
  </figcaption>
 </figure>
}
function LessonOverview({lesson,blocks,checked=[],toggleCheck,setTab,openLesson}){const allParas=blocks.filter(b=>b.type==='paragraph'&&b.paragraph?.text&&b.paragraph.text.trim());const steps=allParas.filter(b=>/^\d+\./.test(b.paragraph.text));const shown=steps.slice(0,10);const doneN=shown.filter((_,i)=>checked.includes(i)).length;const prosa=allParas.filter(b=>!/^\d+\./.test(b.paragraph.text)&&!b.paragraph.headingLevel);const nTab=blocks.filter(b=>b.type==='table').length;const kids=lesson.number?lessons.filter(l=>l.number&&l.number!==lesson.number&&l.number.startsWith(lesson.number+'.')&&l.number.slice(lesson.number.length+1).replace(/\.$/,'').split('.').length===1):[];const parent=lesson.number&&lesson.number.includes('.')?lesson.number.slice(0,lesson.number.lastIndexOf('.')):'';const irmaos=parent?lessons.filter(l=>l.id!==lesson.id&&l.number&&l.number.startsWith(parent+'.')&&l.number.slice(parent.length+1).replace(/\.$/,'').split('.').length===1):[];const vazia=allParas.length===0&&nTab===0;return <article className="lesson-article"><h2>{lesson.number?lesson.number+' · ':''}{lesson.title}</h2><p className="lead">{vazia?'Esta seção abre o tema; o detalhamento está nos tópicos relacionados abaixo.':(kids.length?'Esta seção reúne os tópicos abaixo. Abra cada um para o conteúdo completo.':'Leia com uma pergunta em mente: qual evidência permite avançar, qual lacuna impede a conclusão e qual providência é proporcional.')}</p>{kids.length>0&&<nav className="lesson-children"><strong><Layers3 size={15}/> Tópicos desta seção</strong>{kids.map(c=><button key={c.id} onClick={()=>openLesson&&openLesson(c.id)}><span>{c.number}</span><em>{c.title}</em><ChevronRight size={15}/></button>)}</nav>}{prosa.length>0&&<div className="lesson-keypoints">{prosa.map(b=><p key={b.id}>{b.paragraph.text}</p>)}</div>}{steps.length>=3?<div className="lesson-checklist"><div className="lc-head"><strong><ClipboardCheck size={16}/> Checklist da aula</strong><span>{doneN}/{shown.length} verificados</span><i><em style={{width:`${shown.length?doneN/shown.length*100:0}%`}}/></i></div>{shown.map((b,i)=>{const on=checked.includes(i);return <button type="button" key={b.id} className={on?'lc-item done':'lc-item'} aria-pressed={on} onClick={()=>toggleCheck&&toggleCheck(i)}>{on?<CheckCircle2/>:<Circle/>}<span>{b.paragraph.text.replace(/^\d+\.\s*/,'')}</span></button>})}{doneN===shown.length&&<div className="lc-complete"><Check/> Checklist concluído: você percorreu todos os pontos desta aula.</div>}</div>:null}{vazia&&irmaos.length>0&&<nav className="lesson-children lc-related"><strong><GitBranch size={15}/> Tópicos relacionados nesta parte</strong>{irmaos.slice(0,12).map(c=><button key={c.id} onClick={()=>openLesson&&openLesson(c.id)}><span>{c.number}</span><em>{c.title}</em><ChevronRight size={15}/></button>)}</nav>}{!vazia&&<><div className="analysis-alert"><AlertTriangle/><div><strong>Alerta de análise</strong><p>O conteúdo desta aula apoia a aplicação do POP. Confirme a norma vigente, as regras de transição e as orientações jurídica e institucional aplicáveis ao processo concreto.</p></div></div><div className="example-compare"><div className="bad"><X/><div><strong>Atalho arriscado</strong><p>Assumir a conclusão e procurar documentos apenas para confirmá-la.</p></div></div><div className="good"><Check/><div><strong>Análise rastreável</strong><p>Confrontar evidências, registrar limitações e deixar a conclusão resultar do percurso.</p></div></div></div></>}{(prosa.length>0||steps.length>0||nTab>0)&&<button className="source-jump" onClick={()=>setTab&&setTab('fonte')}><BookMarked/> Consulte o texto integral na aba ao lado</button>}</article>}
function SourceContent({blocks}){if(!blocks.length)return <Empty text="Esta seção é um título de organização do POP: o texto detalhado está nos tópicos da aba Aula. Use o resumo guiado para navegar."/>;return <article className="source-content"><div className="source-notice"><ShieldCheck/><p><strong>Conteúdo integral extraído do documento.</strong> A ordem, os textos e as tabelas foram preservados; blocos de sumário redundantes não entram na experiência didática.</p></div>{blocks.map(b=><BlockRenderer block={b} key={b.id}/>)}</article>}
function BlockRenderer({block}){if(block.type==='table'){const table=tableMap.get(block.tableId);return table?<TableRenderer table={table}/>:null}const p=block.paragraph;if(!p?.text)return null;const figure=figureByBlock.get(block.id);let text=p.text;let cls=p.semanticType==='list-item'||p.list?'source-list':'';return <React.Fragment>{p.headingLevel?<h3>{text}</h3>:<p className={cls}>{text}</p>}{figure&&<figure className="source-figure"><img src={figure.publicPath} alt={figure.altText||figure.title}/><figcaption>{figure.caption}</figcaption></figure>}</React.Fragment>}
function TableRenderer({table,compact=false}){const[all,setAll]=useState(false);const rows=compact||all?table.rows:table.rows.slice(0,12);return <figure className="data-table"><figcaption><span>{table.labelType} {table.labelNumber}</span><strong>{table.title}</strong><small>{table.rowCount} linhas × {table.columnCount} colunas</small></figcaption><div className="table-scroll"><table><tbody>{rows.map((r,ri)=><tr key={ri} className={r.isHeader?'header-row':''}>{r.cells.map((c,ci)=>{const Tag=r.isHeader?'th':'td';return <Tag key={ci}>{c.text}</Tag>})}</tr>)}</tbody></table></div>{!compact&&table.rows.length>12&&<button onClick={()=>setAll(v=>!v)}>{all?'Mostrar menos':`Mostrar todas as ${table.rows.length} linhas`}<ChevronRight/></button>}</figure>}
function LessonMaterials({tables,figures}){if(!tables.length&&!figures.length)return <Empty text="Este tópico não possui quadro ou figura próprio. Consulte o conteúdo integral para o texto-fonte."/>;return <div className="materials-view">{figures.map(f=><figure className="material-figure" key={f.id}><img src={f.publicPath} alt={f.altText||f.title}/><figcaption>{f.caption}</figcaption><a href={f.publicPath} download><Download/> Baixar imagem</a></figure>)}{tables.map(t=><TableRenderer table={t} key={t.id}/>)}</div>}
function Notes({value,setValue}){return <section className="notes-panel"><div><StickyNote/><span><strong>Seu caderno</strong><small>Salvo automaticamente neste dispositivo</small></span></div><textarea value={value} onChange={e=>setValue(e.target.value)} placeholder="Registre dúvidas, exemplos do seu trabalho e pontos para revisar..."/><div className="note-prompts"><button onClick={()=>setValue(value+'\n• Evidência que preciso verificar: ')}>Evidência a verificar</button><button onClick={()=>setValue(value+'\n• Dúvida para validação: ')}>Dúvida para validação</button><button onClick={()=>setValue(value+'\n• Aplicação no meu processo: ')}>Aplicação prática</button></div></section>}

function shuffleIdx(n){const a=[...Array(n).keys()];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function FlowBuilder({flow,record}){const N=flow.nodes.length;const[pool,setPool]=useState(()=>shuffleIdx(N));const[built,setBuilt]=useState([]);useEffect(()=>{setPool(shuffleIdx(N));setBuilt([])},[flow.id]);const done=built.length===N;const score=built.filter((idx,k)=>idx===k).length;useEffect(()=>{if(done)record&&record(flow.id,score,N)},[done]);function place(idx){setBuilt(b=>[...b,idx]);setPool(p=>p.filter(x=>x!==idx))}function undo(){if(!built.length)return;const last=built[built.length-1];setBuilt(b=>b.slice(0,-1));setPool(p=>[...p,last])}function reset(){setPool(shuffleIdx(N));setBuilt([])}return <div className="flow-builder"><div className="fb-head"><h3>Monte a sequência correta</h3><p>Clique nas etapas na ordem em que acontecem no fluxo. A conferência é imediata.</p></div><ol className="fb-slots">{Array.from({length:N}).map((_,k)=>{const idx=built[k];const filled=idx!==undefined;const ok=filled&&idx===k;return <li key={k} className={filled?(ok?'ok':'bad'):'open'}><span>{k+1}</span>{filled?<><strong>{flow.nodes[idx]}</strong>{ok?<Check/>:<X/>}</>:<em>Escolha a etapa {k+1}</em>}</li>})}</ol><div className="fb-pool">{pool.length?pool.map(idx=><button key={idx} onClick={()=>place(idx)}>{flow.nodes[idx]}</button>):<span className="fb-empty">Todas as etapas foram posicionadas.</span>}</div><div className="fb-actions"><button className="text-action" onClick={undo} disabled={!built.length}><RotateCcw size={15}/> Desfazer</button><button className="text-action" onClick={reset}><RefreshCw size={15}/> Recomeçar</button></div>{done&&<div className={'fb-result '+(score===N?'perfect':'')}>{score===N?<CheckCircle2/>:<AlertTriangle/>}<div><strong>{score} de {N} etapas na posição correta</strong><p>{score===N?'Sequência perfeita. Você domina a ordem deste fluxo.':'Revise as etapas em vermelho e recomece para fixar a ordem.'}</p></div></div>}</div>}
function Flowcharts({state,setState}){const[selected,setSelected]=useState(flowSpecs[0].id),[variant,setVariant]=useState('simplificado'),[active,setActive]=useState(0),[playing,setPlaying]=useState(true),[zoom,setZoom]=useState(1),[mode,setMode]=useState('explorar'),[fit,setFit]=useState(true);const flow=flowSpecs.find(f=>f.id===selected);useEffect(()=>{setActive(0);setZoom(1)},[selected]);useEffect(()=>{if(!playing||mode!=='explorar')return;const id=setInterval(()=>setActive(a=>(a+1)%flow.nodes.length),1600);return()=>clearInterval(id)},[playing,flow,mode]);const source=flowData.flowcharts.find(f=>f.number===flow.imageNumber&&f.variant===variant);const record=(id,score,total)=>setState&&setState(s=>({...s,flows:{...(s.flows||{}),[id]:{score,total,date:new Date().toISOString()}}}));const best=state&&state.flows&&state.flows[selected];return <div className="page"><PageHeader title="Fluxogramas interativos" subtitle="Explore os sete fluxos em versão original, simplificada e completa, e acompanhe o caminho ativo." icon={Route}/><div className="flow-workspace"><aside className="flow-menu">{flowSpecs.map((f,i)=><button className={selected===f.id?'active':''} key={f.id} onClick={()=>setSelected(f.id)}><span>{i+1}</span><div><strong>{f.title}</strong><small>{state&&state.flows&&state.flows[f.id]?`Montado ${state.flows[f.id].score}/${state.flows[f.id].total}`:'Explorar e montar'}</small></div><ChevronRight/></button>)}</aside><section className="flow-canvas"><div className="flow-mode-tabs"><button className={mode==='explorar'?'active':''} onClick={()=>setMode('explorar')}><Eye/> Explorar</button><button className={mode==='montar'?'active':''} onClick={()=>setMode('montar')}><GitBranch/> Montar o fluxo</button>{best&&<span className="fb-badge"><CheckCircle2/> {best.score}/{best.total}</span>}</div>{mode==='explorar'?<><div className="flow-toolbar"><span className="flow-toolbar-label">Percurso didático em {flow.nodes.length} etapas</span><div><button onClick={()=>setPlaying(v=>!v)}>{playing?<Pause/>:<Play/>}</button><button onClick={()=>setZoom(z=>Math.max(.7,z-.1))}><ZoomOut/></button><span>{Math.round(zoom*100)}%</span><button onClick={()=>setZoom(z=>Math.min(1.4,z+.1))}><ZoomIn/></button></div></div><div className="interactive-flow" style={{transform:`scale(${zoom})`}}>{flow.nodes.map((n,i)=><React.Fragment key={n}><button className={(i===active?'active ':'')+(i<active?'visited ':'')+(n.includes('?')?'decision':'')} onClick={()=>{setActive(i);setPlaying(false)}}><span>{i+1}</span><strong>{n}</strong><small>{i===active?'Etapa em foco':i<active?'Percorrida':'A seguir'}</small></button>{i<flow.nodes.length-1&&<div className={(i<active?'lit':'')}><ArrowRight/></div>}</React.Fragment>)}</div><div className="flow-insight"><Info/><div><small>ETAPA {active+1}</small><h3>{flow.nodes[active]}</h3><p>Abra o conteúdo do POP, confira as evidências e registre a motivação antes de avançar. Clique em qualquer nó para explorar.</p></div></div></>:<FlowBuilder flow={flow} record={record}/>}<section className="source-flow-panel"><div className="sfp-head"><span className="sfp-title"><Eye/> Fluxograma-fonte do POP</span><div className="variant-tabs">{[['original','Original'],['simplificado','Simplificado'],['completo','Completo']].map(([v,l])=><button className={variant===v?'active':''} onClick={()=>setVariant(v)} key={v}>{l}</button>)}</div><button className="sfp-fit" onClick={()=>setFit(f=>!f)}>{fit?'Ver em tamanho real':'Ajustar à largura'}</button>{source&&<a className="sfp-open" href={source.publicPath} target="_blank" rel="noreferrer"><Maximize2/> Nova aba</a>}</div>{source?<div className={'sfp-scroll '+(fit?'fit':'real')}><img key={source.publicPath} src={source.publicPath} alt={`${flow.title}, versão ${variant}`}/></div>:<p className="sfp-missing">Imagem não encontrada para esta versão.</p>}{source&&<small className="sfp-meta">Versão {variant} · {source.widthPx}×{source.heightPx}px · imagem integral do documento</small>}</section></section></div></div>}

function Laboratory({state,setState}){const[selected,setSelected]=useState(scenarios[2].id),[answers,setAnswers]=useState({}),[reason,setReason]=useState(''),[showResult,setShowResult]=useState(false),[showSummary,setShowSummary]=useState(false),[seenEv,setSeenEv]=useState({});const s=scenarios.find(x=>x.id===selected);useEffect(()=>{setAnswers({});setReason('');setShowResult(false);setShowSummary(false);setSeenEv({})},[selected]);const answered=Object.keys(answers).length;const score=s.questions.filter((q,i)=>answers[i]===q[1]).length;function finish(){setShowResult(true);setState(st=>({...st,labs:{...st.labs,[s.id]:{score,total:s.questions.length,date:new Date().toISOString()}}}))}return <div className="page lab-page"><PageHeader title="Pratique antes de assinar" subtitle="Laboratório didático: selecione evidências, tome decisões e compare sua fundamentação." icon={FlaskConical}/><div className="lab-acervo"><Database size={16}/><p><strong>Retrato real do acervo</strong> (agregado e anônimo, jul/2026): 1.598 processos hidrelétricos: 58% CGH, 31% PCH, 6% UHE. Quase metade das licenças históricas constam vencidas e 53% dos processos têm coordenada só da barragem. Os cenários abaixo treinam exatamente esses padrões.</p></div><div className="scenario-tabs">{scenarios.map(x=><button className={selected===x.id?'active':''} onClick={()=>{setSelected(x.id);setTimeout(()=>document.querySelector('.lab-workspace')?.scrollIntoView({behavior:'smooth',block:'start'}),70)}} key={x.id}>{x.label}{state.labs[x.id]&&<CheckCircle2/>}</button>)}</div><div className="lab-workspace"><section className="lab-canvas" key={selected}><div className="case-header"><div><small>CENÁRIO · {s.type}</small><h2>{s.title}</h2></div><button className={showSummary?'active':''} onClick={()=>setShowSummary(v=>!v)}><FileText/> Resumo do caso</button></div>{showSummary&&<div className="case-summary"><p><strong>{s.title}</strong>, cenário de {s.type}.</p><ul>{s.facts.map(f=><li key={f}>{f}</li>)}</ul><p>{s.evidence.length} evidências disponíveis · {s.questions.length} decisões no percurso · debriefing ao finalizar.</p></div>}<div className="case-facts">{s.facts.map(f=><span key={f}><Activity/>{f}</span>)}</div><div className="decision-path"><div className="path-node complete"><span>1</span><strong>Triagem</strong><Check/></div>{s.questions.map((q,i)=><React.Fragment key={q[0]}><i className={answers[i]?'active':''}/><button className={'path-node '+(answers[i]?'complete ':'')+(i===answered?'current':'')} onClick={()=>{const el=document.querySelectorAll('.question-stack fieldset')[i];el&&el.scrollIntoView({behavior:'smooth',block:'center'})}}><span>{i+2}</span><strong>{(s.steps&&s.steps[i])||('Etapa '+(i+2))}</strong>{answers[i]?<Check/>:<Circle/>}</button></React.Fragment>)}<i className={answered===s.questions.length?'active':''}/><div className={'path-node '+(showResult?'complete':'')}><span>{s.questions.length+2}</span><strong>Parecer</strong>{showResult?<Check/>:<Circle/>}</div></div><div className="lab-evidence"><div><h3>Evidências disponíveis</h3>{s.evidence.map(e=><button key={e} className={seenEv[e]?'seen':''} onClick={()=>setSeenEv(v=>({...v,[e]:!v[e]}))}><FileText/><span>{e}<small>{seenEv[e]?'Consultada':'Documento do cenário'}</small></span>{seenEv[e]?<CheckCircle2/>:<Eye/>}</button>)}</div><div className="question-stack"><h3>Decisões do percurso</h3>{s.questions.map((q,i)=><fieldset key={q[0]} className={i>answered?'locked':''}><legend>{i+1}. {q[0]}</legend>{i>answered?<span><Lock/> Responda à etapa anterior</span>:<div><button className={answers[i]==='sim'?'selected':''} onClick={()=>setAnswers(a=>({...a,[i]:'sim'}))}>Sim</button><button className={answers[i]==='nao'?'selected':''} onClick={()=>setAnswers(a=>({...a,[i]:'nao'}))}>Não</button></div>}</fieldset>)}</div></div></section><aside className="lab-inspector"><div><small>SEU PARECER DIDÁTICO</small><h2>Fundamente a decisão</h2><p>Relacione evidências, consequência técnica e encaminhamento.</p></div><textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Escreva sua fundamentação..."/><div className="decision-readiness"><span>Decisões respondidas <b>{answered}/{s.questions.length}</b></span><i><em style={{width:`${answered/s.questions.length*100}%`}}/></i><span>Fundamentação <b>{reason.length}/30 mín.</b></span><i><em style={{width:`${Math.min(100,reason.length/30*100)}%`}}/></i></div><button className="primary" disabled={answered<s.questions.length||reason.length<30} onClick={finish}>Finalizar e ver debriefing <ArrowRight/></button><div className="lab-tip"><Lightbulb/><p><strong>Dica do laboratório</strong> Não procure apenas “sim” ou “não”: explicite por que a evidência é suficiente ou insuficiente.</p></div>{showResult&&<div className="debrief"><Trophy/><small>DEBRIEFING</small><h3>{score}/{s.questions.length} decisões alinhadas</h3><p>{s.outcome}</p><button onClick={()=>{setAnswers({});setReason('');setShowResult(false)}}><RotateCcw/> Tentar novamente</button></div>}</aside></div></div>}

function Assessments({state,setState}){const[track,setTrack]=useState('geral'),[started,setStarted]=useState(false),[index,setIndex]=useState(0),[answers,setAnswers]=useState({}),[revealed,setRevealed]=useState(false),[done,setDone]=useState(false);const questions=useMemo(()=>{if(track!=='geral')return questionBank.filter(q=>q.track===track);const byTrack=new Map();for(const q of questionBank){if(!byTrack.has(q.track))byTrack.set(q.track,[]);byTrack.get(q.track).push(q)}const picked=[];for(let round=0;picked.length<12&&round<questionBank.length;round++){for(const t of tracks){const qs=byTrack.get(t.id);if(qs&&qs[round]&&picked.length<12)picked.push(qs[round])}}return picked},[track]);const q=questions[index];const score=questions.filter((x,i)=>answers[i]===x.answer).length;function reset(id=track){setTrack(id);setStarted(false);setIndex(0);setAnswers({});setRevealed(false);setDone(false)}function next(){if(index===questions.length-1){setDone(true);setState(s=>({...s,quizScores:{...s.quizScores,[track]:{score,total:questions.length,date:new Date().toISOString()}}}))}else{setIndex(i=>i+1);setRevealed(false)}}return <div className="page"><PageHeader title="Avaliações e domínio" subtitle="Questões comentadas transformam erro em revisão direcionada, sem esconder o fundamento." icon={ClipboardCheck}/>{!started?<div className="assessment-select"><section className="diagnostic"><div><Award/><span><small>AVALIAÇÃO INTEGRADORA</small><h2>Diagnóstico geral do POP</h2><p>12 questões distribuídas pelos módulos do POP, dos fundamentos à conclusão técnica.</p></span></div><div className="assessment-meta"><span><Clock/> 15 min</span><span><MessageSquareText/> Feedback imediato</span><span><Trophy/> Registro de resultado</span></div><button onClick={()=>{reset('geral');setStarted(true)}}>Iniciar diagnóstico <ArrowRight/></button>{state.quizScores.geral&&<small>Último resultado: {state.quizScores.geral.score}/{state.quizScores.geral.total}</small>}</section><h2>Avaliações por módulo</h2><div className="module-tests">{tracks.filter(t=>questionBank.some(q=>q.track===t.id)).map(t=>{let qs=questionBank.filter(q=>q.track===t.id),last=state.quizScores[t.id];return <button key={t.id} onClick={()=>{reset(t.id);setStarted(true)}}><span style={{background:t.color}}>{t.code}</span><div><strong>{t.title}</strong><small>{qs.length} questões · feedback comentado</small></div>{last?<b>{last.score}/{last.total}</b>:<ChevronRight/>}</button>})}</div></div>:<section className="quiz-stage">{done?<div className="quiz-result"><div className="score-ring" style={{'--score':`${score/questions.length*100}%`}}><span><strong>{score}</strong>/{questions.length}</span></div><h2>{score/questions.length>=.8?'Domínio consistente':'Há pontos para revisar'}</h2><p>Você acertou {Math.round(score/questions.length*100)}%. Use o feedback abaixo para voltar às trilhas relacionadas.</p><div className="result-actions"><button onClick={()=>{reset();setStarted(true)}}><RotateCcw/> Refazer</button><button className="primary" onClick={()=>setStarted(false)}>Escolher outra avaliação</button></div></div>:<><div className="quiz-top"><button onClick={()=>setStarted(false)}><ChevronLeft/> Sair</button><span>Questão {index+1} de {questions.length}</span><i><em style={{width:`${(index+1)/questions.length*100}%`}}/></i></div><div className="quiz-question"><small>{tracks.find(t=>t.id===q.track)?.code} · CONHECIMENTO APLICADO</small><h2>{q.question}</h2><div className="quiz-options">{q.options.map((o,i)=><button disabled={revealed} className={(answers[index]===i?'selected ':'')+(revealed&&i===q.answer?'correct ':'')+(revealed&&answers[index]===i&&i!==q.answer?'wrong':'')} onClick={()=>setAnswers(a=>({...a,[index]:i}))} key={o}><span>{String.fromCharCode(65+i)}</span>{o}{revealed&&i===q.answer&&<Check/>}</button>)}</div>{revealed&&<div className={answers[index]===q.answer?'answer-feedback correct':'answer-feedback'}><Lightbulb/><div><strong>{answers[index]===q.answer?'Resposta correta':'Ponto de revisão'}</strong><p>{q.explanation}</p></div></div>}<div className="quiz-actions">{!revealed?<button className="primary" disabled={answers[index]===undefined} onClick={()=>setRevealed(true)}>Confirmar resposta</button>:<button className="primary" onClick={next}>{index===questions.length-1?'Ver resultado':'Próxima questão'}<ArrowRight/></button>}</div></div></>}</section>}</div>}

const LEI_DOMINIOS=[['BRASIL','planalto.gov.br'],['CONAMA','conama.mma.gov.br'],['PARANÁ','legislacao.pr.gov.br'],['INSTITUTO ÁGUA E TERRA','iat.pr.gov.br'],['AGÊNCIA NACIONAL','aneel.gov.br'],['INSTITUTO DO PATRIMÔNIO','gov.br/iphan'],['ABNT','abnt.org.br']];
function leiDominio(ref){const hit=LEI_DOMINIOS.find(([org])=>ref.toUpperCase().startsWith(org));return hit?hit[1]:null}
function leiTokens(ref){const toks=[];const m=ref.match(/n[ºo°]\s*([\d.]+)/);if(m)toks.push(m[1]);const iat=ref.match(/IN(?:strução Normativa)?\s+IAT\s+n[ºo°]\s*(\d+)/i);if(iat)toks.push('IN IAT nº '+iat[1].replace(/^0/,''),'IN IAT nº '+iat[1]);return toks.filter(t=>t.length>2)}
function KnowledgeLibrary({state,openLesson}){const[tab,setTab]=useState('buscar'),[query,setQuery]=useState(''),[selectedTable,setSelectedTable]=useState(popData.tables.find(t=>!t.navigationOnly)?.id);
 const leis=useMemo(()=>{const s=popData.sections.find(x=>/refer[eê]ncias normativas/i.test(x.title||''));return((s?.blockIds)||[]).map(id=>blockMap.get(id)?.paragraph?.text||'').filter(Boolean)},[]);
 const[leiSel,setLeiSel]=useState(0);
 const leiCitacoes=useMemo(()=>{const ref=leis[leiSel]||'';const toks=leiTokens(ref);if(!toks.length)return[];const out=[];for(const l of lessons){for(const id of(l.blockIds||[])){const t=blockMap.get(id)?.paragraph?.text||'';if(t&&toks.some(tk=>t.includes(tk))&&!/^(BRASIL|CONAMA|PARANÁ|INSTITUTO|AGÊNCIA|ABNT)/.test(t)){out.push({lesson:l,text:t});if(out.length>=10)return out}}}return out},[leiSel,leis]);const index=useMemo(()=>[...lessons.map(l=>({type:'seção',id:l.id,title:`${l.number||''} ${l.title}`.trim(),text:sectionText(l)})),...popData.tables.filter(t=>!t.navigationOnly).map(t=>({type:'tabela',id:t.id,title:t.caption,text:t.rows.map(r=>r.cells.map(c=>c.text).join(' ')).join(' ')}))],[]);const matches=query.length>1?index.filter(x=>norm(x.title+' '+x.text).includes(norm(query))):[];const results=matches.slice(0,50);const table=tableMap.get(selectedTable);const glossary=popData.tables.find(t=>/siglas e abreviações/i.test(t.title));return <div className="page"><PageHeader title="Biblioteca operacional" subtitle={`Pesquise no texto integral, abra os ${popData.tables.filter(t=>!t.navigationOnly).length} quadros e tabelas e consulte todas as imagens do material-fonte.`} icon={Library}/><div className="library-tabs">{[['buscar','Buscar no POP',Search],['tabelas','Quadros e tabelas',Table2],['figuras','Figuras e fluxos',ImageIcon],['glossario','Glossário',BookMarked],['legislacoes','Legislações',Scale],['favoritos','Meus favoritos',Bookmark]].map(([id,l,I])=><button className={tab===id?'active':''} onClick={()=>setTab(id)} key={id}><I/>{l}</button>)}</div>{tab==='buscar'&&<section className="library-search"><div className="big-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ex.: transferência de titularidade, PACUERA, APP, condicionante..."/><kbd>{matches.length>results.length?`${results.length} de ${matches.length}`:matches.length} resultados</kbd></div>{query.length<2?<div className="search-start"><Database/><h2>{(popData.stats?.allDocumentParagraphNodes||0).toLocaleString('pt-BR')} parágrafos pesquisáveis</h2><p>A busca percorre todas as seções e o conteúdo das tabelas, preservando o vínculo com a aula correspondente.</p><div>{['PACUERA','regra de transição','Licença de Operação','cartografia','condicionantes'].map(x=><button onClick={()=>setQuery(x)} key={x}>{x}</button>)}</div></div>:<div className="search-results">{results.map(r=><button key={r.id} onClick={()=>r.type==='seção'?openLesson(r.id):(setSelectedTable(r.id),setTab('tabelas'))}><span>{r.type}</span><div><strong>{r.title}</strong><p>{snippet(r.text,query)}</p></div><ChevronRight/></button>)}</div>}</section>}{tab==='tabelas'&&<div className="table-library"><aside><div><Filter/><span>{popData.tables.length} tabelas · {popData.tables.filter(t=>t.navigationOnly).length} índices ocultos na trilha</span></div>{popData.tables.filter(t=>!t.navigationOnly).map(t=><button className={selectedTable===t.id?'active':''} onClick={()=>setSelectedTable(t.id)} key={t.id}><span>{t.labelType} {t.labelNumber}</span><strong>{t.title}</strong></button>)}</aside><section>{table&&<TableRenderer table={table}/>}</section></div>}{tab==='figuras'&&<div className="figure-library"><h2>Figuras do POP</h2><div className="figure-grid">{popData.figures.map(f=><figure key={f.id}><button onClick={()=>window.open(f.publicPath,'_blank')}><img src={f.publicPath} alt={f.altText||f.title}/><span><Maximize2/></span></button><figcaption>{f.caption}</figcaption></figure>)}</div><h2>Fluxogramas comparados</h2><div className="flow-gallery">{flowData.flowcharts.map(f=><figure key={f.id}><a href={f.publicPath} target="_blank" rel="noreferrer"><img src={f.publicPath} alt={`${f.title} · ${f.variant}`}/></a><figcaption><span>{f.variant}</span><strong>{f.number}. {f.title}</strong></figcaption></figure>)}</div></div>}{tab==='glossario'&&<div className="glossary-view"><div><h2>Siglas e abreviações</h2><p>Consulta rápida extraída do Anexo E.</p></div>{glossary&&<TableRenderer table={glossary}/>}</div>}{tab==='legislacoes'&&<div className="leis-view"><aside className="leis-list"><div className="leis-head"><Scale/><span>{leis.length} normas referenciadas no POP</span></div>{leis.map((l,i)=><button key={i} className={leiSel===i?'active':''} onClick={()=>{setLeiSel(i);if(window.innerWidth<980)setTimeout(()=>document.querySelector('.leis-detail')?.scrollIntoView({behavior:'smooth',block:'start'}),60)}}><small>{l.split('.')[0]}</small><strong>{l.replace(/^[^.]+\.\s*/,'').split('. ')[0]}</strong></button>)}</aside><section className="leis-detail">{leis[leiSel]&&<><h2>{leis[leiSel].replace(/^[^.]+\.\s*/,'').split('. ')[0]}</h2><p className="leis-ref"><BookMarked size={15}/> Referência integral registrada no POP: <em>{leis[leiSel]}</em></p><div className="leis-actions">{leiDominio(leis[leiSel])&&<a className="primary" href={'https://www.google.com/search?q='+encodeURIComponent('"'+(leis[leiSel].match(/n[ºo°]\s*[\d.]+[^,.]*/)?.[0]||leis[leiSel].slice(0,50))+'" site:'+leiDominio(leis[leiSel]))} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Íntegra oficial ({leiDominio(leis[leiSel])})</a>}</div>{resumoDaNorma(leis[leiSel])&&<div className="leis-resumo"><h3>Sobre esta norma</h3><p>{resumoDaNorma(leis[leiSel])}</p></div>}<h3>Onde o POP aplica esta norma</h3>{leiCitacoes.length?<ul className="leis-cites">{leiCitacoes.map((c,k)=><li key={k}><button onClick={()=>openLesson(c.lesson.id)}><small>{c.lesson.number?c.lesson.number+' · ':''}{c.lesson.title}</small><p>{c.text.length>260?c.text.slice(0,260)+'…':c.text}</p></button></li>)}</ul>:<p className="leis-none">Esta norma consta da lista de referências do POP; o resumo acima orienta o contexto de aplicação.</p>}</>}</section></div>}{tab==='favoritos'&&<div className="favorites-view">{(()=>{const favs=state.bookmarks.map(id=>lessonMap.get(id)).filter(Boolean);return favs.length?favs.map(l=><button key={l.id} onClick={()=>openLesson(l.id)}><BookmarkCheck/><span><small>{tracks.find(t=>t.id===l.trackId)?.code}</small><strong>{l.number?`${l.number} `:''}{l.title}</strong></span><ChevronRight/></button>):<Empty text="Você ainda não salvou nenhuma aula. Use o ícone de favorito no cabeçalho de uma aula."/>})()}</div>}</div>}

function GlobalSearch({close,openLesson}){const[q,setQ]=useState('');const input=useRef();useEffect(()=>input.current?.focus(),[]);const results=q.length>1?lessons.filter(l=>norm(l.title+' '+l.number+' '+sectionText(l)).includes(norm(q))).slice(0,12):[];return <div className="search-modal" role="dialog" aria-modal="true"><button className="modal-scrim" onClick={close} aria-label="Fechar busca"/><section><div className="modal-input"><Search/><input ref={input} value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&results.length)openLesson(results[0].id)}} placeholder="Buscar no POP e nas aulas..."/><kbd>ESC</kbd></div>{q.length<2?<div className="modal-empty"><Sparkles/><p>Pesquise uma fase, documento, norma, sigla ou critério.</p></div>:<div className="modal-results">{results.map(l=><button onClick={()=>openLesson(l.id)} key={l.id}><span>{tracks.find(t=>t.id===l.trackId)?.code}</span><div><strong>{l.number?`${l.number} `:''}{l.title}</strong><small>{snippet(sectionText(l),q)}</small></div><ChevronRight/></button>)}{!results.length&&<Empty text="Nenhum tópico encontrado. Tente outro termo."/>}</div>}<footer><span><kbd>↵</kbd> abrir</span><span><kbd>ESC</kbd> fechar</span><small>Busca local: nenhum dado é enviado</small></footer></section></div>}
function snippet(text,q){let clean=(text||'').replace(/\s+/g,' ').trim();let pos=norm(clean).indexOf(norm(q));if(pos<0)return clean.slice(0,180)+(clean.length>180?'…':'');return(pos>45?'…':'')+clean.slice(Math.max(0,pos-45),pos+145)+(pos+145<clean.length?'…':'')}
function PageHeader({title,subtitle,icon:Icon,kicker}){return <header className="page-header"><span><Icon/></span><div>{kicker&&<small className="ph-kicker">{kicker}</small>}<h1>{title}</h1><p>{subtitle}</p></div></header>}
function Empty({text}){return <div className="empty-state"><BookOpen/><p>{text}</p></div>}

createRoot(document.getElementById('root')).render(<App/>);
